+      }

+      // Even if parsing fails, we must move to the body state. This prevents
+      // infinite buffering of the body into m_headers.
       m_state = nsIMsgParseMailMsgState::ParseBodyState;
+
+      NS_ENSURE_SUCCESS(rv, rv);
     } else {
